import {accountingGroup,buildMonthly,leaveKinds,leaveStates} from './monthly.mjs';
import {zipStored} from "./xlsx.mjs";
import {periodStart} from "./model.mjs";
const templates={"project": "", "category": ""};
const xml = value => String(value ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g,'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const dayText = date => date.toISOString().slice(0,10);
const shortDate = day => Number(day.slice(5,7))+'/'+Number(day.slice(8));
function column(number) {
 let name='';
 while(number){number--;name=String.fromCharCode(65+number%26)+name;number=Math.floor(number/26);}
 return name;
}
function setCell(sheet,ref,value,formula){
 const style = sheet.original.get(ref);
 if(style===undefined)throw Error('底表缺少欄位 '+ref);
 const start='<c r="'+ref+'"'+(style?' s="'+style+'"':'');
 const end=formula ? (typeof value==='string'?' t="str"':'')+'><f>'+xml(formula)+'</f><v>'+xml(value)+'</v></c>'
  : typeof value==='number'?'><v>'+value+'</v></c>': ' t="inlineStr"><is><t xml:space="preserve">'+xml(value)+'</t></is></c>';
 sheet.cells.set(ref,start+end);
}
function prepareSheet(source){
 const original=new Map();
 // Match self-closing styled cells without consuming the following cell.
 const cellsPattern=/<c\b(?=[^>]*\br="([A-Z]+\d+)")[^>]*?(?:\/>|>[\s\S]*?<\/c>)/g;
 for(const m of source.matchAll(cellsPattern))original.set(m[1],m[0].match(/\bs="(\d+)"/)?.[1]||'');
 const sheet={original,cells:new Map()};
 sheet.finish=()=>source.replace(cellsPattern,(cell,ref)=>sheet.cells.get(ref)??cell);
 return sheet;
}
const layout={
 project:{design:[5,13,21,29,37],construction:[46,56],internal:[67]},
 category:{soft:[5,9,13,17,21,25,29,33],account:[46],admin:[57],other:[41]},
 daily:{mon:[5],tue:[13],wed:[21],thu:[29],fri:[37],sat:[46],sun:[56]}
};
const dailyKinds=['sun','mon','tue','wed','thu','fri','sat'];
function lane(style,e){
 if(style==='daily'){const k=dailyKinds[new Date(e.work_date+'T00:00:00Z').getUTCDay()];return [k,k,['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][dailyKinds.indexOf(k)]];}
 if(style==='project')return [e.business,e.project_id||'internal',e.projectName];
 return accountingGroup(e,e.projectName);
}
function slots(style,row){
 if(style==='category')return row===46?[46,50,54]:row===57?[57,61,65]:[row,row+1,row+2,row+3];
 const length=row===67?3:row>=46?10:8;
 return Array.from({length},(_,i)=>row+i);
}
function groupPages(style,entries,weeks){
 const pages=[],groups=new Map(),next=new Map();
 for(const e of entries){
  const week=periodStart(e.work_date,'week');if(!weeks.includes(week))continue;
  const [kind,key,label]=lane(style,e),id=JSON.stringify([kind,key]);
  if(!groups.has(id))groups.set(id,{kind,label,items:new Map()});
  const items=groups.get(id).items;if(!items.has(week))items.set(week,[]);items.get(week).push(e);
 }
 for(const group of groups.values()){
  const blocks=layout[style][group.kind];if(!blocks)throw Error('不支援的工作分類 '+group.kind);
  const remaining=new Map([...group.items].map(([w,v])=>[w,[...v]]));
  do{
   const i=next.get(group.kind)||0;next.set(group.kind,i+1);
   const page=Math.floor(i/blocks.length),row=blocks[i%blocks.length],lines=slots(style,row);
   pages[page]??=[];pages[page].push({row,lines,label:group.label,items:weeks.map(w=>(remaining.get(w)||[]).splice(0,lines.length))});
  }while([...remaining.values()].some(a=>a.length));
 }
 return pages.length?pages:[[]];
}
function calendarWeeks(data){
 const byWeek=new Map(),withData=new Set([...data.entries,...data.leaves||[]].map(e=>e.work_date));
 for(let date=new Date(data.month.slice(0,7)+'-01T00:00:00Z');dayText(date).startsWith(data.month.slice(0,7));date.setUTCDate(date.getUTCDate()+1)){
  const day=dayText(date),minutes=data.calendar?.[day];
  if(!Number.isSafeInteger(minutes)||minutes<0)throw Error('缺少公司班表 '+day+'，請重新載入月報');
  if(!minutes&&!withData.has(day))continue;
  const key=periodStart(day,'week');if(!byWeek.has(key))byWeek.set(key,{key,days:[],minutes:0});
  const w=byWeek.get(key);w.days.push(day);w.minutes+=minutes;
 }
 return [...byWeek.values()];
}
function plainSheet(rows){
 return '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cols><col min="1" max="10" width="22" customWidth="1"/></cols><sheetData>'+rows.map((row,i)=>'<row r="'+(i+1)+'">'+row.map((v,j)=>'<c r="'+column(j+1)+(i+1)+'"'+(typeof v==='number'?'><v>'+v+'</v>':' t="inlineStr"><is><t xml:space="preserve">'+xml(v)+'</t></is>')+'</c>').join('')+'</row>').join('')+'</sheetData></worksheet>';
}
export async function companyDocument(data,style,projects,person){
 if(!Object.hasOwn(layout,style))throw Error('月報版型無效');
 if(data.month!==periodStart(data.month,'month'))throw Error('請選擇有效報表月份');
 for(const row of [...data.entries,...data.leaves||[],...data.plans||[]]){
  if(row.employee_id&&row.employee_id!==person.employeeId)throw Error('月報人員不符');
 }
 const summary=buildMonthly(data,style,projects);
 const template=style==='category'?'category':'project';
 const bytes=Uint8Array.from(atob(templates[template]),c=>c.charCodeAt(0));
 const files=JSON.parse(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text());
 const source=files['xl/worksheets/sheet1.xml'],weeks=calendarWeeks(data);
 const names=new Map((data.reportProjects??projects).map(p=>[p.project_id,p.name]));
 const entries=data.entries.map(e=>{
  if(e.employee_id!==person.employeeId||!e.work_date.startsWith(data.month.slice(0,7)))throw Error('月報人員或月份不符');
  return {...e,projectName:e.project_name||names.get(e.project_id)||(e.project_id?'專案 '+e.project_id:'內部事務')};
 }).sort((a,b)=>a.work_date.localeCompare(b.work_date)||a.id.localeCompare(b.id));
 if(new Set(entries.map(e=>e.id)).size!==entries.length)throw Error('工作明細重複');
 const standard=weeks.reduce((sum,w)=>sum+w.minutes,0)/60;
 const complete=entries.every(e=>Number.isInteger(e.actual_minutes));
 const actual=entries.reduce((sum,e)=>sum+(e.actual_minutes??0),0)/60;
 const visibleLeaves=(data.leaves||[]).filter(l=>l.status==='approved'||l.status==='pending');
 const daysWithLeave=style==='daily'?visibleLeaves.map(l=>({
  work_date:l.work_date,leave:l,
  work_type:leaveKinds.find(([key])=>key===l.leave_kind)?.[1]||'請假',
  description:shortDate(l.work_date)+' · '+leaveStates[l.status]+' · '+l.minutes/60+'h'
 })):[];
 const printed=[...entries,...daysWithLeave].sort((a,b)=>a.work_date.localeCompare(b.work_date));
 const batches=[];
 for(let offset=0;offset<Math.max(1,weeks.length);offset+=5){
  const batch=weeks.slice(offset,offset+5);
  for(const groups of groupPages(style,printed,batch.map(w=>w.key)))batches.push({batch,groups,offset});
 }
 const totalRow=style==='category'?68:71;
 const totalsRefs=batches.map((_,i)=>"'"+(i?'月報續頁'+(i+1):'專案月報表')+"'!AQ"+totalRow);
 const totalsRange=(batches.length===1?"'專案月報表'":"'專案月報表:月報續頁"+batches.length+"'")+'!AQ'+totalRow;
 const added=[],pages=[];let pageNo=0;
 function addSheet(name,content,printArea){
  const n=added.length+2;files['xl/worksheets/sheet'+n+'.xml']=content;
  const id='rIdLeaves'+n;
  files['xl/workbook.xml']=files['xl/workbook.xml'].replace('</sheets>','<sheet name="'+name+'" sheetId="'+(100+n)+'" r:id="'+id+'"/></sheets>');
  files['xl/_rels/workbook.xml.rels']=files['xl/_rels/workbook.xml.rels'].replace('</Relationships>','<Relationship Id="'+id+'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'+n+'.xml"/></Relationships>');
  files['[Content_Types].xml']=files['[Content_Types].xml'].replace('</Types>','<Override PartName="/xl/worksheets/sheet'+n+'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');
  if(printArea){const index=(template==='project'?2:1)+added.length;files['xl/workbook.xml']=files['xl/workbook.xml'].replace('</definedNames>','<definedName name="_xlnm.Print_Area" localSheetId="'+index+'">'+name+'!$A$1:$AQ$'+printArea+'</definedName></definedNames>');}
  added.push(name);
 }
 for(const {batch,groups,offset} of batches){
   const sheet=prepareSheet(source),put=(r,v,f)=>setCell(sheet,r,v,f);pageNo++;
   put('D2',data.month.slice(0,4)+'年');put('E2',Number(data.month.slice(5,7)));put('AL2',(data.reportName||person.name));
   put('AC1','每月標準工作時數 '+standard+' 小時');put('AK1',standard);
   put('AF1',complete?actual:'待確認','IF(OR('+totalsRefs.map(ref=>ref+'="待確認"').join(',')+'),"待確認",SUM('+totalsRange+'))');put('AM1',complete?actual-standard:'','IF(ISNUMBER(AF1),AF1-AK1,"")');
   const blockRows=Object.values(layout[style]).flat();
   for(let w=0;w<5;w++){
    const col=8+w*7,ref=(delta,row)=>column(col+delta)+row,week=batch[w];
    put(ref(0,3),week?'第'+(offset+w+1)+'週':'');put(ref(0,4),week?shortDate(week.days[0])+(week.days.length>1?'–'+shortDate(week.days.at(-1)):''):'');put(ref(2,4),week?week.minutes/60:'');
    for(const row of blockRows){put(ref(4,row),'');put(ref(5,row),'');if(style==='daily')for(const line of slots(style,row))put(ref(0,line),'');}
    for(const g of groups){
     put('B'+g.row,g.label);const items=g.items[w]||[];if(!items.length)continue;
     items.forEach((e,i)=>{const row=g.lines[i];put(ref(0,row),e.work_type);put(ref(1,row),e.leave?e.description:(style==='daily'?shortDate(e.work_date)+' '+e.projectName+' · ':'')+e.description+'（預 '+e.planned_minutes/60+'h，實 '+(e.actual_minutes===null?'待確認':e.actual_minutes/60+'h')+'）');});
     const work=items.filter(e=>!e.leave);if(!work.length)continue;
     put(ref(4,g.row),work.reduce((n,e)=>n+e.planned_minutes,0)/60);
     put(ref(5,g.row),work.some(e=>e.actual_minutes===null)?'待確認':work.reduce((n,e)=>n+e.actual_minutes,0)/60);
    }
   }
   if(style==='daily'){put('A5','平日');put('A46','週末');}

   function sumRefs(target,refs,values){const v=values.includes(null)?'待確認':values.length?values.reduce((a,b)=>a+b,0)/60:'';put(target,v,'IF('+refs.map(r=>'('+r+'="待確認")').join('+')+',"待確認",IF(COUNT('+refs.join(',')+')=0,"",SUM('+refs.join(',')+')))');}
   for(const row of blockRows){const items=groups.find(g=>g.row===row)?.items.flat().filter(e=>!e.leave)||[];sumRefs('AQ'+row,[13,20,27,34,41].map(c=>column(c)+row),items.map(e=>e.actual_minutes));}
   for(let w=0;w<5;w++){
    const items=groups.flatMap(g=>g.items[w]||[]).filter(e=>!e.leave);
    for(const [c,field]of [[12,'planned_minutes'],[13,'actual_minutes']]){const col=column(c+w*7);sumRefs(col+totalRow,blockRows.map(r=>col+r),items.map(e=>e[field]));}
   }
   sumRefs('AQ'+totalRow,blockRows.map(r=>'AQ'+r),groups.flatMap(g=>g.items.flat()).filter(e=>!e.leave).map(e=>e.actual_minutes));
   pages.push({name:pageNo===1?'專案月報表':'月報續頁'+pageNo,xml:sheet.finish(),bindings:Object.fromEntries(groups.flatMap(g=>g.items.flatMap((items,w)=>items.flatMap((e,i)=>e.leave?[]:[[column(8+w*7)+g.lines[i],[e.id]],[column(9+w*7)+g.lines[i],[e.id]]]))))});
   if(pageNo===1)files['xl/worksheets/sheet1.xml']=sheet.finish();else addSheet('月報續頁'+pageNo,sheet.finish(),totalRow+1);
 }
 addSheet('工時明細',plainSheet([['固定 ID','姓名','月份','狀態','每月標準小時'],[person.employeeId,(data.reportName||person.name),data.month.slice(0,7),data.closed?(data.legacyContext?'已核定（舊版，表頭依現有資料）':'已核定'):'草稿',standard],['班表小時','已確認假時數','扣除已確認假後的應工作小時','待確認假時數','已填實際工作小時','實際待確認筆數'],[standard,summary.leaveTotals.approved/60,Math.max(0,standard-summary.leaveTotals.approved/60),summary.leaveTotals.pending/60,summary.actual/60,summary.missing],['日期','專案','業務','類別','內容','預計小時','實際小時'],...entries.map(e=>[e.work_date,e.projectName,e.business,e.work_type,e.description,e.planned_minutes/60,e.actual_minutes===null?'待確認':e.actual_minutes/60])]));
 addSheet('請假與期間計畫',plainSheet([['請假日期','假別','狀態','請假小時'],...(data.leaves||[]).map(l=>[l.work_date,({sick:'病假',personal:'事假',annual:'特休',other:'其他'})[l.leave_kind],({approved:'已確認',pending:'待確認',withdrawn:'已撤回',rejected:'未通過'})[l.status],l.minutes/60]),[],['計畫起日','期間','專案','類別','內容','期間預計小時'],...(data.plans||[]).map(p=>[p.period_start,p.period_kind,names.get(p.project_id)||p.project_id||'內部事務',p.work_type,p.description,p.planned_minutes/60])]));
 return {files,pages};
}

export async function companyWorkbook(...args){return zipStored((await companyDocument(...args)).files);}
